module accu(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [1:0] count;
reg [7:0] data_in_reg [3:0];
reg [9:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        valid_out <= 0;
        data_out <= 0;
        data_in_reg <= '{default: 0};
        sum <= 0;
    end else begin
        if (valid_in) begin
            data_in_reg[count] <= data_in;
            count <= count + 1;
            if (count == 2'd3) begin
                sum <= data_in_reg[0] + data_in_reg[1] + data_in_reg[2] + data_in_reg[3];
                data_out <= sum;
                valid_out <= 1;
                count <= 0;
            end else begin
                valid_out <= 0;
            end
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule
